#!/usr/bin/env bash
# W1 policies evaluator (DEER/EAT/NTC/oracle from saved probes, no GPU).
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing W1 policies evaluator..."
decode "scripts/ntc_w1_policies.py" << 'B64EOF'

B64EOF
echo ""
echo "Installed. Run (instant, no GPU):"
echo "  python scripts/ntc_w1_policies.py --probes experiments/ntc/w1_math500_Qwen3-4B.json"